    case {PMsg, NMsg} of
        {#{payload := {event, OPFpayload}}, #{payload := {event, ONFpayload}}} -> S2#{payload => {event, 'merge_msg_faultmesh.v1.Event'(OPFpayload, ONFpayload, TrUserData)}};
        {_, #{payload := NFpayload}} -> S2#{payload => NFpayload};
        {#{payload := PFpayload}, _} -> S2#{payload => PFpayload};
        {_, _} -> S2
    end.

