verify_msg(Msg, MsgName) when is_atom(MsgName) -> verify_msg(Msg, MsgName, []).

verify_msg(Msg, MsgName, Opts) ->
    TrUserData = proplists:get_value(user_data, Opts),
    case MsgName of
        'faultmesh.v1.StreamRequest' -> 'v_msg_faultmesh.v1.StreamRequest'(Msg, [MsgName], TrUserData);
        'faultmesh.v1.StreamResponse' -> 'v_msg_faultmesh.v1.StreamResponse'(Msg, [MsgName], TrUserData);
        'faultmesh.v1.IngestAck' -> 'v_msg_faultmesh.v1.IngestAck'(Msg, [MsgName], TrUserData);
        'faultmesh.v1.ActionRequest' -> 'v_msg_faultmesh.v1.ActionRequest'(Msg, [MsgName], TrUserData);
        'faultmesh.v1.TailRequest' -> 'v_msg_faultmesh.v1.TailRequest'(Msg, [MsgName], TrUserData);
        'faultmesh.v1.TailEvent' -> 'v_msg_faultmesh.v1.TailEvent'(Msg, [MsgName], TrUserData);
        'faultmesh.v1.Event' -> 'v_msg_faultmesh.v1.Event'(Msg, [MsgName], TrUserData);
        'faultmesh.v1.MetricPoint' -> 'v_msg_faultmesh.v1.MetricPoint'(Msg, [MsgName], TrUserData);
        'google.protobuf.Timestamp' -> 'v_msg_google.protobuf.Timestamp'(Msg, [MsgName], TrUserData);
        _ -> mk_type_error(not_a_known_message, Msg, [])
    end.


